import{_ as d,a0 as n,w as l,s as i,ao as p,I as s,x as t,a1 as r,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"检查linux中硬盘损坏的扇区和区块 | LCTT x X-CMD","titleTemplate":false,"description":"检查linux中硬盘损坏的扇区和区块 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"检查linux中硬盘损坏的扇区和区块 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"检查linux中硬盘损坏的扇区和区块 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140808 Check Hard drive for bad sectors or bad blocks in linux","title":"检查linux中硬盘损坏的扇区和区块","tag":"201408","desc":""},"relativePath":"201408/20140808 Check Hard drive for bad sectors or bad blocks in linux.md","filePath":"[post].md"}'),u={name:"201408/20140808 Check Hard drive for bad sectors or bad blocks in linux.md"};function b(f,e,k,x,c,m){const a=n("Link");return l(),i("div",null,[e[13]||(e[13]=p(`<h1 id="检查linux中硬盘损坏的扇区和区块" tabindex="-1">检查linux中硬盘损坏的扇区和区块 <a class="header-anchor" href="#检查linux中硬盘损坏的扇区和区块" aria-label="Permalink to “检查linux中硬盘损坏的扇区和区块”">​</a></h1><p><strong>badblocks</strong>是linux及其类似的操作系统中，扫描检查硬盘和外部设备损坏扇区的命令工具。损坏的扇区或者损坏的区块是硬盘中因为永久损坏或者是操作系统不能读取的空间。</p><p>Badblocks命令可以探测硬盘中所有损坏的扇区或者区块并将结果保存在一个文本文档中，这样，我们就可以使用<strong>e2fsck</strong>命令来配置操作系统不在这些损坏的扇区中存储数据。</p><h3 id="步骤-1-使用fdisk命令识别硬盘信息" tabindex="-1">步骤:1 使用fdisk命令识别硬盘信息 <a class="header-anchor" href="#步骤-1-使用fdisk命令识别硬盘信息" aria-label="Permalink to “步骤:1 使用fdisk命令识别硬盘信息”">​</a></h3><pre><code># sudo fdisk -l 
</code></pre><h3 id="步骤-2-扫描硬盘的损坏扇区或区块" tabindex="-1">步骤:2 扫描硬盘的损坏扇区或区块 <a class="header-anchor" href="#步骤-2-扫描硬盘的损坏扇区或区块" aria-label="Permalink to “步骤:2  扫描硬盘的损坏扇区或区块”">​</a></h3><pre><code># sudo badblocks -v /dev/sdb &gt; /tmp/bad-blocks.txt
</code></pre><p>只需将“/dev/sdb”替换为自己机器的硬盘/分区。执行完成上述命令后，一个名为“bad-blocks”文本文档将会在/tmp下创建，它将包含所有的损坏区块。</p><p>例如：</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2014/08/badblocks.png" alt=""></p><h3 id="步骤-3-提示-操作系统不要使用损坏区块存储" tabindex="-1">步骤:3 提示 操作系统不要使用损坏区块存储 <a class="header-anchor" href="#步骤-3-提示-操作系统不要使用损坏区块存储" aria-label="Permalink to “步骤:3 提示 操作系统不要使用损坏区块存储”">​</a></h3><p>扫描完成后，如果损坏区块被发现了，然后通过e2fsck命令使用“bad-blocks.txt”，强迫操作系统不使用这些损坏的区块存储数据。</p><pre><code># sudo e2fsck -l /tmp/bad-blocks.txt  /dev/sdb
</code></pre><p>注意：在运行e2fsck命令前，请保证设备没有被挂载。</p><p>关于badblocks和e2fsck命令的更多帮助，请参考下列man页面</p><pre><code># man badblocks
# man e2fsck  
</code></pre><hr>`,17)),s("p",null,[e[1]||(e[1]=t("via: ",-1)),r(a,{href:"http://www.linuxtechi.com/check-hard-drive-for-bad-sector-linux/"},{default:o(()=>[...e[0]||(e[0]=[t("http://www.linuxtechi.com/check-hard-drive-for-bad-sector-linux/",-1)])]),_:1})]),s("p",null,[e[5]||(e[5]=t("作者：",-1)),r(a,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:o(()=>[...e[2]||(e[2]=[t("Pradeep Kumar",-1)])]),_:1}),e[6]||(e[6]=t(" 译者：",-1)),r(a,{href:"http://www.vicyu.net"},{default:o(()=>[...e[3]||(e[3]=[t("Vic___",-1)])]),_:1}),e[7]||(e[7]=t(" 校对：",-1)),r(a,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...e[4]||(e[4]=[t("Caroline",-1)])]),_:1})]),s("p",null,[e[10]||(e[10]=t("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创翻译，",-1)),r(a,{href:"http://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const w=d(u,[["render",b]]);export{C as __pageData,w as default};
